"""PL-03 step 4: write the JSON report."""

import json
from collections.abc import Mapping, Sequence
from dataclasses import asdict
from pathlib import Path

from risk.types import Drawdown, Report, TickerSummary


def write_report(
    summary: Sequence[TickerSummary], drawdowns: Sequence[Drawdown], out_path: str | Path
) -> Report:
    """Write one row per ticker (REP-01); `ValueError` if the two cover different tickers."""
    by_ticker = {d.ticker: d for d in drawdowns}
    summary_tickers = [s.ticker for s in summary]
    if sorted(summary_tickers) != sorted(by_ticker) or len(by_ticker) != len(drawdowns):
        raise ValueError(
            f"summary covers {sorted(summary_tickers)}, drawdowns cover "
            f"{sorted(d.ticker for d in drawdowns)}"
        )
    rows = tuple(
        _row(s, by_ticker[s.ticker]) for s in sorted(summary, key=lambda s: s.ticker)
    )
    Path(out_path).write_text(json.dumps({"tickers": rows}, indent=2) + "\n")
    return Report(path=str(out_path), rows=rows)


def _row(summary: TickerSummary, drawdown: Drawdown) -> Mapping[str, object]:
    return {
        **asdict(summary),
        "max_drawdown": drawdown.depth,
        "peak_date": drawdown.peak_date,
        "trough_date": drawdown.trough_date,
    }

